mkdir -p src/pages src/theme && cat > src/main.tsx <<'EOF'
// Gravity UI base styles (fonts first, then base styles) — must be imported once at the entry point.
import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';
import './app.css';

import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';

import { App } from './App';

// ThemeProvider lives inside <App /> so the theme toggle can control it.
ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <BrowserRouter>
      <App />
    </BrowserRouter>
  </React.StrictMode>,
);
EOF
cat > src/app.css <<'EOF'
/* Full-height app frame: the AsideHeader content area scrolls, not the document. */
html,
body,
#root {
  height: 100%;
  margin: 0;
}
