      </Label>
    ),
  },
];

export function TeamPage() {
  return (
    <Page title="Команда" description="Список участников проекта.">
      <Table<Member>
        data={MEMBERS}
        columns={COLUMNS}
        getRowId="id"
        emptyMessage="Участников пока нет"
      />
      <Text variant="caption-2" color="hint">
        Всего участников: {MEMBERS.length}
      </Text>
    </Page>
  );
}
